import { expect } from "bun:test"
import path from "path"
import fc from "fast-check"
import { Effect } from "effect"
import { LayerNode } from "@opencode-ai/core/effect/layer-node"
import { FSUtil } from "@opencode-ai/core/fs-util"
import { Agent } from "../../src/agent/agent"
import { MessageID, SessionID } from "../../src/session/schema"
import { RepositoryOverviewTool } from "../../src/tool/repository-overview"
import { Tool } from "../../src/tool/tool"
import { Truncate } from "../../src/tool/truncate"
import { TestInstance, withTmpdirInstance } from "../fixture/fixture"
import { testEffect } from "../lib/effect"

fc.configureGlobal({ seed: 20261111 })

const it = testEffect(LayerNode.compile(LayerNode.group([FSUtil.node, Truncate.node, Agent.node])))

const ctx = {
  sessionID: SessionID.make("ses_property"),
  messageID: MessageID.make("msg_property"),
  agent: "build",
  abort: AbortSignal.any([]),
  messages: [],
  metadata: () => Effect.void,
  ask: () => Effect.void,
} satisfies Tool.Context

// Independent oracle: these expected kinds describe the repository contract.
const recognizedFiles = [
  { path: "README.md", kind: "readme" },
  { path: "readme.txt", kind: "readme" },
  { path: "README.backup.tmp", kind: "readme" },
  { path: "package.json", kind: "manifest" },
  { path: "pyproject.toml", kind: "manifest" },
  { path: "Cargo.toml", kind: "manifest" },
  { path: "go.mod", kind: "manifest" },
  { path: "bun.lock", kind: "lockfile" },
  { path: "pnpm-lock.yaml", kind: "lockfile" },
  { path: "tsconfig.json", kind: "config" },
  { path: "vite.config.ts", kind: "config" },
  { path: "next.config.mjs", kind: "config" },
] as const

const irrelevantFiles = ["notes.txt", "NOTREADME.md", "source.ts", ".env", "Dockerfile"]

const importantFilesProperty = fc.record({
  recognized: fc.subarray(recognizedFiles, { minLength: 1 }),
  irrelevant: fc.uniqueArray(fc.constantFrom(...irrelevantFiles), {
    maxLength: irrelevantFiles.length,
  }),
})

it.live("R1 recognizes generated important files", () =>
  Effect.gen(function* () {
    const services = yield* Effect.context<FSUtil.Service | Agent.Service | Truncate.Service>()

    yield* Effect.promise(() =>
      fc.assert(
        fc.asyncProperty(importantFilesProperty, async ({ recognized, irrelevant }) => {
          await Effect.gen(function* () {
            const test = yield* TestInstance
            const fs = yield* FSUtil.Service

            yield* Effect.forEach(recognized, (file) =>
              fs.writeFileString(path.join(test.directory, file.path), ""),
            )
            yield* Effect.forEach(irrelevant, (file) =>
              fs.writeFileString(path.join(test.directory, file), ""),
            )

            const info = yield* RepositoryOverviewTool
            const tool = yield* info.init()
            const result = yield* tool.execute({}, ctx)

            const expected = [...recognized]
              .map((file) => ({ path: file.path, kind: file.kind }))
              .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))

            expect(result.metadata.overview.importantFiles).toEqual(expected)
            expect(JSON.parse(result.output).importantFiles).toEqual(expected)
          }).pipe(withTmpdirInstance(), Effect.scoped, Effect.provide(services), Effect.runPromise)
        }),
        { numRuns: 50 },
      ),
    )
  }),
)

import path from "path"
import { Effect, Option, Schema } from "effect"
import { FSUtil } from "@opencode-ai/core/fs-util"
import { InstanceState } from "@/effect/instance-state"
import { LANGUAGE_EXTENSIONS } from "@/lsp/language"
import { Tool } from "./tool"
import DESCRIPTION from "./repository-overview.txt"

const EXCLUDED = new Set([
  "node_modules",
  ".git",
  "dist",
  "build",
  "coverage",
  ".next",
  ".nuxt",
  ".turbo",
  ".cache",
  "target",
  "vendor",
  ".venv",
  "venv",
  "__pycache__",
])

const FILES = new Map<string, "manifest" | "lockfile" | "config">([
  ["package.json", "manifest"],
  ["pyproject.toml", "manifest"],
  ["Cargo.toml", "manifest"],
  ["go.mod", "manifest"],
  ["bun.lock", "lockfile"],
  ["bun.lockb", "lockfile"],
  ["package-lock.json", "lockfile"],
  ["pnpm-lock.yaml", "lockfile"],
  ["yarn.lock", "lockfile"],
  ["tsconfig.json", "config"],
  ["jsconfig.json", "config"],
  ["vite.config.ts", "config"],
  ["vite.config.js", "config"],
  ["vite.config.mts", "config"],
  ["vite.config.mjs", "config"],
  ["next.config.js", "config"],
  ["next.config.mjs", "config"],
  ["next.config.ts", "config"],
])

export const Parameters = Schema.Struct({})

export const MAX_COLLECTION_ITEMS = 100
export const MAX_WORKSPACE_STEPS = 1000
export const MAX_TECHNOLOGY_DIRECTORIES = 1000
export const MAX_TEXT_LENGTH = 1024
export const MAX_OUTPUT_BYTES = 32 * 1024

const PackageMetadata = Schema.Struct({
  name: Schema.optional(Schema.Unknown),
  packageManager: Schema.optional(Schema.Unknown),
  workspaces: Schema.optional(Schema.Unknown),
  dependencies: Schema.optional(Schema.Unknown),
  devDependencies: Schema.optional(Schema.Unknown),
})

const LANGUAGES = new Map([
  ["typescript", "TypeScript"],
  ["typescriptreact", "TypeScript"],
  ["javascript", "JavaScript"],
  ["javascriptreact", "JavaScript"],
  ["python", "Python"],
  ["go", "Go"],
  ["rust", "Rust"],
  ["java", "Java"],
])

const LANGUAGE_FILES = new Map([
  ["tsconfig.json", "TypeScript"],
  ["jsconfig.json", "JavaScript"],
  ["pyproject.toml", "Python"],
  ["Cargo.toml", "Rust"],
  ["go.mod", "Go"],
  ["pom.xml", "Java"],
  ["build.gradle", "Java"],
  ["build.gradle.kts", "Java"],
])

const FRAMEWORKS = new Map([
  ["react", "React"],
  ["next", "Next.js"],
  ["vue", "Vue"],
  ["svelte", "Svelte"],
  ["@angular/core", "Angular"],
  ["express", "Express"],
])

const WorkspaceDeclaration = Schema.Union([
  Schema.Array(Schema.String),
  Schema.Struct({ packages: Schema.Array(Schema.String) }),
])

const MANAGERS = new Map([
  ["bun.lock", "bun"],
  ["bun.lockb", "bun"],
  ["pnpm-lock.yaml", "pnpm"],
  ["yarn.lock", "yarn"],
  ["package-lock.json", "npm"],
])

export const RepositoryOverviewTool = Tool.define(
  "repository_overview",
  Effect.gen(function* () {
    const fs = yield* FSUtil.Service
    return {
      description: DESCRIPTION,
      parameters: Parameters,
      execute: (_params, ctx) =>
        Effect.gen(function* () {
          const instance = yield* InstanceState.context
          const readPackageMetadata = (directory: string) => {
            const file = path.join(directory, "package.json")
            return Effect.gen(function* () {
              yield* ctx.ask({
                permission: "read",
                patterns: [path.relative(instance.worktree, file)],
                always: ["*"],
                metadata: { path: file },
              })
              return yield* fs.readJson(file).pipe(
                Effect.map(Schema.decodeUnknownOption(PackageMetadata)),
                Effect.map(Option.getOrNull),
                Effect.catch(() => Effect.succeed(null)),
              )
            })
          }
          const reasons = new Set<string>()
          const bounded = <T>(items: T[], field: string) => {
            if (items.length > MAX_COLLECTION_ITEMS) reasons.add(field)
            return items.slice(0, MAX_COLLECTION_ITEMS)
          }
          const text = (value: string, field: string) => {
            if (value.length > MAX_TEXT_LENGTH) reasons.add(field)
            return value.slice(0, MAX_TEXT_LENGTH)
          }
          yield* ctx.ask({
            permission: "repository_overview",
            patterns: [instance.directory],
            always: ["*"],
            metadata: { path: instance.directory },
          })
          const entries = yield* fs.readDirectoryEntries(instance.directory)
          const manifest = entries.some((entry) => entry.type === "file" && entry.name === "package.json")
            ? yield* readPackageMetadata(instance.directory)
            : null
          const explicit =
            typeof manifest?.packageManager === "string"
              ? /^(bun|pnpm|yarn|npm)@(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?)$/.exec(
                  manifest.packageManager,
                )
              : null
          const lockfiles = entries
            .filter((entry) => entry.type === "file" && MANAGERS.has(entry.name))
            .map((entry) => entry.name)
            .sort()
          const managers = new Set(lockfiles.map((file) => MANAGERS.get(file)!))
          const declaration = Option.getOrNull(Schema.decodeUnknownOption(WorkspaceDeclaration)(manifest?.workspaces))
          const patterns = declaration === null ? [] : "packages" in declaration ? declaration.packages : declaration
          const workspacePatterns = bounded(
            [
              ...new Set(
                patterns.flatMap((pattern) => {
                  // Only relative, in-repository patterns are eligible. Never follow symlinks.
                  if (path.posix.isAbsolute(pattern) || path.win32.isAbsolute(pattern) || /[\\!]/.test(pattern))
                    return []
                  const segments = pattern.split("/").filter((segment) => segment !== "." && segment !== "")
                  if (!segments.length || segments.some((segment) => segment === ".." || EXCLUDED.has(segment)))
                    return []
                  if (pattern.length > MAX_TEXT_LENGTH) {
                    reasons.add("workspacePatternLength")
                    return []
                  }
                  return [segments.join("/")]
                }),
              ),
            ].sort(),
            "workspacePatterns",
          )
          const budget = { remaining: MAX_WORKSPACE_STEPS, matches: new Set<string>(), reasons }
          for (const pattern of workspacePatterns) {
            yield* resolveWorkspaces(fs, instance.directory, pattern.split("/"), budget)
          }
          const workspaces = yield* Effect.forEach(
            bounded([...budget.matches].filter((directory) => directory !== instance.directory).sort(), "workspaces"),
            (directory) =>
              Effect.gen(function* () {
                const files = yield* fs.readDirectoryEntries(directory).pipe(Effect.catch(() => Effect.succeed([])))
                const child = files.some((entry) => entry.type === "file" && entry.name === "package.json")
                  ? yield* readPackageMetadata(directory)
                  : null
                return {
                  path: path.relative(instance.directory, directory).split(path.sep).join("/"),
                  name: typeof child?.name === "string" && child.name.trim() ? text(child.name, "workspaceName") : null,
                  technologies: detectTechnologies(files, child),
                }
              }),
          )
          const technologies = [detectTechnologies(entries, manifest), ...workspaces.map((item) => item.technologies)]
          // Technology evidence belongs to the repository, not to workspace
          // membership: a literal declaration can become stale after a rename.
          const detected = new Set([
            instance.directory,
            ...workspaces.map((item) => path.join(instance.directory, item.path)),
          ])
          const directories = [instance.directory]
          for (let index = 0; index < directories.length && index < MAX_TECHNOLOGY_DIRECTORIES; index++) {
            const directory = directories[index]
            const files =
              directory === instance.directory
                ? entries
                : yield* fs.readDirectoryEntries(directory).pipe(
                    Effect.catch(() => {
                      reasons.add("technologyRead")
                      return Effect.succeed([])
                    }),
                  )
            if (!detected.has(directory)) {
              const child = files.some((entry) => entry.type === "file" && entry.name === "package.json")
                ? yield* readPackageMetadata(directory)
                : null
              technologies.push(detectTechnologies(files, child))
            }
            directories.push(
              ...files
                .filter((entry) => entry.type === "directory" && !EXCLUDED.has(entry.name))
                .map((entry) => path.join(directory, entry.name))
                .sort(),
            )
          }
          if (directories.length > MAX_TECHNOLOGY_DIRECTORIES) reasons.add("technologyTraversal")
          const overview = {
            root: text(instance.directory, "root"),
            name: text(path.basename(instance.directory), "name"),
            workspacePatterns,
            workspaces: workspaces.map((item) => ({ path: item.path, name: item.name })),
            languages: [...new Set(technologies.flatMap((item) => item.languages))].sort(),
            frameworks: [...new Set(technologies.flatMap((item) => item.frameworks))].sort(),
            package: manifest
              ? {
                  name:
                    typeof manifest.name === "string" && manifest.name.trim()
                      ? text(manifest.name, "packageName")
                      : null,
                }
              : null,
            packageManager: explicit
              ? {
                  name: explicit[1],
                  version: text(explicit[2], "packageManagerVersion"),
                  source: "package.json#packageManager",
                }
              : managers.size === 1
                ? { name: MANAGERS.get(lockfiles[0])!, version: null, source: lockfiles[0] }
                : null,

